SELECT name FROM students WHERE city IN ('Lahore', 'Multan');

SELECT name, age FROM students WHERE age BETWEEN 20 AND 22;

SELECT name FROM students WHERE name LIKE '%a';

SELECT name FROM students
WHERE id IN (SELECT student_id FROM enrollments WHERE grade >= 90);

SELECT name FROM students s
WHERE NOT EXISTS (SELECT 1 FROM enrollments e WHERE e.student_id = s.id);

SELECT s.name, (SELECT COUNT(*) FROM enrollments e WHERE e.student_id = s.id) AS courses_taken
FROM students s
ORDER BY courses_taken DESC, s.name
LIMIT 3;

SELECT ROUND(AVG(total), 1) AS average_total
FROM (SELECT student_id, SUM(grade) AS total FROM enrollments GROUP BY student_id);

INSERT INTO students VALUES (1, 'Duplicate', 'Lahore', 30);

INSERT INTO enrollments VALUES (99, 1, 50);

INSERT INTO students (id, city) VALUES (9, 'Lahore');

CREATE VIEW top_grades AS
SELECT s.name, c.title, e.grade
FROM enrollments e
JOIN students s ON s.id = e.student_id
JOIN courses c ON c.id = e.course_id
WHERE e.grade >= 85;

SELECT * FROM top_grades ORDER BY grade DESC;

SELECT COUNT(*) AS rows_in_view FROM top_grades;
